module find_min_T(\n    input clk,\n    input rst_n,\n    input start,\n    input [1:0] teacher_0, teacher_1, teacher_2, teacher_3, teacher_4, teacher_5,\n    input [2:0] pref_0_0, pref_0_1, pref_0_2, pref_0_3, pref_0_4,\n    input [2:0] pref_1_0, pref_1_1, pref_1_2, pref_1_3, pref_1_4,\n    input [2:0] pref_2_0, pref_2_1, pref_2_2, pref_2_3, pref_2_4,\n    input [2:0] pref_3_0, pref_3_1, pref_3_2, pref_3_3, pref_3_4,\n    input [2:0] pref_4_0, pref_4_1, pref_4_2, pref_4_3, pref_4_4,\n    input [2:0] pref_5_0, pref_5_1, pref_5_2, pref_5_3, pref_5_4,\n    output reg [3:0] T,\n    output reg done\n);\n\nlocalparam N = 6;  \nlocalparam LOG_N = 3;\nlocalparam MAX_T = 5;  \n\n// State definitions\nlocalparam [2:0] IDLE        = 3'd0;\nlocalparam [2:0] COMPUTE_MASKS = 3'd1;\nlocalparam [2:0] CHECK       = 3'd2;\nlocalparam [2:0] ENUMERATE   = 3'd3;\nlocalparam [2:0] FOUND       = 3'd4;\nlocalparam [2:0] INCREMENT_T = 3'd5;\nlocalparam [2:0] DONE_STATE  = 3'd6;\n\nreg [2:0] state;\n\n// Internal storage\nreg [1:0] stored_teacher [0:5];\nreg [2:0] stored_pref [0:5][0:4];\n\n// Mask arrays\nreg [5:0] mask [0:5];\n\n// Assignment odometer\nreg [1:0] assigned_teacher [0:5];\n\n// Counters and flags\nreg [3:0] current_i;      // Mask computation counter\nreg [3:0] current_pos;    \nreg [3:0] i_check, j_check;  // CHECK state counters\nreg checking_a;            // CHECK substate flag\nreg valid;                 // Assignment validity\nreg all_assignments_done;  // Enumeration complete\ninteger k;  // Loop iterator\n\n// Input combining comb logic\nalways @(*) begin\n    {stored_teacher[0], stored_teacher[1], stored_teacher[2], stored_teacher[3], stored_teacher[4], stored_teacher[5]} =\n        {teacher_0, teacher_1, teacher_2, teacher_3, teacher_4, teacher_5};\n    {stored_pref[0][0], stored_pref[0][1], stored_pref[0][2], stored_pref[0][3], stored_pref[0][4]} = {pref_0_0, pref_0_1, pref_0_2, pref_0_3, pref_0_4};\n    {stored_pref[1][0], stored_pref[1][1], stored_pref[1][2], stored_pref[1][3], stored_pref[1][4]} = {pref_1_0, pref_1_1, pref_1_2, pref_1_3, pref_1_4};\n    {stored_pref[2][0], stored_pref[2][1], stored_pref[2][2], stored_pref[2][3], stored_pref[2][4]} = {pref_2_0, pref_2_1, pref_2_2, pref_2_3, pref_2_4};\n    {stored_pref[3][0], stored_pref[3][1], stored_pref[3][2], stored_pref[3][3], stored_pref[3][4]} = {pref_3_0, pref_3_1, pref_3_2, pref_3_3, pref_3_4};\n    {stored_pref[4][0], stored_pref[4][1], stored_pref[4][2], stored_pref[4][3], stored_pref[4][4]} = {pref_4_0, pref_4_1, pref_4_2, pref_4_3, pref_4_4};\n    {stored_pref[5][0], stored_pref[5][1], stored_pref[5][2], stored_pref[5][3], stored_pref[5][4]} = {pref_5_0, pref_5_1, pref_5_2, pref_5_3, pref_5_4};\nend\n\nalways @(posedge clk or negedge rst_n) begin\n    if (!rst_n) begin\n        state <= IDLE;\n        T <= 4'd0;\n        done <= 1'b0;\n        current_i <= 4'd0;\n        current_pos <= 4'd0;\n        checking_a <= 1'b1;\n        valid <= 1'b1;\n        i_check <= 4'd0;\n        j_check <= 4'd0;\n        all_assignments_done <= 1'b0;\n        for (k=0; k<6; k=k+1) begin\n            mask[k] <= 6'd0;\n            assigned_teacher[k] <= 2'd0;\n        end\n    end else begin\n        case (state)\n            IDLE: begin\n                done <= 1'b0;\n                if (start) begin\n                    T <= 4'd0;\n                    current_i <= 4'd0;\n                    current_pos <= 4'd0;\n                    for (k=0; k<6; k=k+1) mask[k] <= 6'd0;\n                    state <= COMPUTE_MASKS;\n                end\n            end\n            \n            COMPUTE_MASKS: begin\n                if (current_i < 6) begin\n                    if (current_pos < T && current_pos < 5) begin  // Prevent overflow\n                        mask[current_i][stored_pref[current_i][current_pos]] <= 1'b1;\n                        current_pos <= current_pos + 1;\n                    end else begin\n                        current_i <= current_i + 1;\n                        current_pos <= 4'd0;\n                    end\n                end else begin\n                    // Initialize assignment check\n                    for (k=0; k<6; k=k+1) assigned_teacher[k] <= 2'd0;\n                    valid <= 1'b1;\n                    checking_a <= 1'b1;\n                    i_check <= 4'd0;\n                    j_check <= 4'd0;\n                    state <= CHECK;\n                end\n            end\n            \n            CHECK: begin\n                if (checking_a) begin  // Condition A: teacher mismatch\n                    if (i_check < 6) begin\n                        if (assigned_teacher[i_check] == stored_teacher[i_check]) valid <= 1'b0;\n                        i_check <= i_check + 1;\n                    end else begin\n                        checking_a <= 1'b0;\n                        i_check <= 4'd0;\n                        j_check <= 4'd1;  // Start j = i+1\n                    end\n                end else begin  // Condition B: mutual top-T\n                    if (i_check < 5) begin  // i from 0-4\n                        if (j_check < 6) begin\n                            if (j_check > i_check) begin  // Avoid duplicate pairs\n                                if (assigned_teacher[i_check] == assigned_teacher[j_check]) begin\n                                    if (!mask[i_check][j_check] || !mask[j_check][i_check]) valid <= 1'b0;\n                                end\n                            end\n                            j_check <= j_check + 1;\n                        end else begin\n                            i_check <= i_check + 1;\n                            j_check <= i_check + 4'd1;  // j = i+1\n                        end\n                    end else begin\n                        // All checks complete\n                        if (valid) state <= FOUND;\n                        else state <= ENUMERATE;\n                        // Reset check variables\n                        valid <= 1'b1;\n                        checking_a <= 1'b1;\n                        i_check <= 4'd0;\n                        j_check <= 4'd0;\n                    end\n                end\n            end\n            \n            ENUMERATE: begin\n                // Base-3 increment with carry\n                reg carry;\n                carry = 1'b1;\n                for (k=0; k<6; k=k+1) begin\n                    if (carry) begin\n                        if (assigned_teacher[k] < 2'd2) begin\n                            assigned_teacher[k] <= assigned_teacher[k] + 1'd1;\n                            carry = 1'b0;\n                        end else begin\n                            assigned_teacher[k] <= 2'd0;\n                            carry = 1'b1;\n                        end\n                    end\n                end\n                if (carry) all_assignments_done <= 1'b1;\n                \n                if (all_assignments_done) state <= INCREMENT_T;\n                else state <= CHECK;\n            end\n            \n            FOUND: begin\n                done <= 1'b1;\n                state <= DONE_STATE;\n            end\n            \n            INCREMENT_T: begin\n                if (T < MAX_T) begin\n                    T <= T + 1'b1;\n                    current_i <= 4'd0;\n                    current_pos <= 4'd0;\n                    all_assignments_done <= 1'b0;\n                    for (k=0; k<6; k=k+1) mask[k] <= 6'd0;\n                    state <= COMPUTE_MASKS;\n                end else begin\n                    state <= DONE_STATE;\n                end\n            end\n            \n            DONE_STATE: begin\n                done <= 1'b0;\n                // Stay until reset\n            end\n            \n            default: state <= IDLE;\n        endcase\n    end\nend\n\nendmodule